def call_structured(prompt, schema, max_repair=2):
    msg = prompt
    for attempt in range(max_repair + 1):
        raw = call_model(msg, response_format=schema)
        try:
            data = schema.validate(raw)      # syntactic + schema
            assert is_semantically_valid(data)  # ชั้นที่ 3
            return data
        except (SchemaError, AssertionError) as e:
            # แนบ error กลับไปให้โมเดลแก้เอง
            msg = prompt + '\n\nผลก่อนหน้าผิดเพราะ: ' + str(e)
    raise OutputError('ซ่อมไม่สำเร็จหลังลอง ' + str(max_repair) + ' ครั้ง')

import random, time

def retry_with_backoff(fn, max_attempts=5, base=0.5, cap=8.0):
    for attempt in range(max_attempts):
        try:
            return fn()
        except TransientError:
            if attempt == max_attempts - 1:
                raise
            delay = min(cap, base * (2 ** attempt))  # 0.5, 1, 2, 4, 8...
            delay += random.uniform(0, delay * 0.3)   # jitter กันยิงพร้อมกัน
            time.sleep(delay)
